class ptr32(int):
    def __getitem__(self, _: int) -> int:
        ...

    def __setitem__(self, _: int, _2: int) -> None:
        ...

class ptr8(int):
    def __getitem__(self, _: int) -> int:
        ...

    def __setitem__(self, _: int, _2: int) -> None:
        ...

def uint(_: int) -> int:
    ...

# TODO: Volume support
# TODO: Calculate wait time between cycles.
@micropython.viper
def jit_sample_buf(dest: ptr32, src: ptr8, len: int, delta_cycles: int):
    rtc_word_len = (len - 1) * 2

    for rtc_addr in range(0, rtc_word_len, 2):
        sample_addr: int = rtc_addr >> 1

        #print(f"src offset {src_offset} idx {src_offset + (rtc_addr >> 3)}")
        sample = src[sample_addr]
        #print(f"got sample {sample} at idx {sample_addr}")
        dest[rtc_addr] = (_ULP_INSTR_REG_WR_TEMPLATE | (sample << _ULP_INSTR_REG_WR_DATA_OFFSET))
        dest[rtc_addr + 1] = uint(_ULP_INSTR_WAIT_TEMPLATE) | delta_cycles

        # # FOR TESTING REASONS
        # if sample > int(max_amp):
        #     max_amp = sample
        # elif sample < int(min_amp):
        #     min_amp = sample

    # NOTE: Last sample in the array has extra wait cycles (due to branching logic)
    # Account for this in the wait logic.
    dest[rtc_word_len] = (_ULP_INSTR_REG_WR_TEMPLATE | (src[len - 1] << _ULP_INSTR_REG_WR_DATA_OFFSET))
    dest[rtc_word_len + 1] = uint(_ULP_INSTR_WAIT_TEMPLATE) | (delta_cycles - 25)

@micropython.viper
def _zero_sample_buf(dest: ptr32, len: int, delta_cycles: int):
    d_wr = (127 << _ULP_INSTR_REG_WR_DATA_OFFSET)

    for rtc_addr in range(0, len * 2, 2):
        dest[rtc_addr] = _ULP_INSTR_REG_WR_TEMPLATE | d_wr
        dest[rtc_addr + 1] = int(_ULP_INSTR_WAIT_TEMPLATE) | delta_cycles

class AudioPlayer:
    def __init__(self):
        pass

    def initialize(self, wave_file: Wave_read, ram_buffer_mult: int):
        self.audio_f = wopen(wave_file)

        # TODO: Resample channels if unsupported.
        channels = self.audio_f.getnchannels()
        sample_sz = self.audio_f.getsampwidth()
        framerate = self.audio_f.getframerate()
        frame_cnt = self.audio_f.getnframes()

        # Driver only currently supports 1 channel 8 bit audio
        # Will add support for resampling later.

        print(f"channels {channels} sample_sz {sample_sz}B/s framerate {framerate} frame_cnt {frame_cnt}")

        # TODO: VOLUME ADJUST NOT YET SUPPORTED
        self.vol_recip = 1
        self.sample_buffer_size = ram_buffer_mult * _RTC_BUFFER_SLICE_WIDTH 
        self.sample_buffer = memoryview(bytearray(self.sample_buffer_size))
        self.sample_buffer_ptr = self.sample_buffer_size - 1  # So ISR will refill it
        self.sample_cycles_delta = _RTC_FAST_CLK_HZ // framerate - _ULP_CLKS_WRITE_DELAY
        self.ulp = ULP()

        self.ulp.load_binary(0, ulp_img)
        print(f"sample dt {self.sample_cycles_delta} cycles {self.sample_cycles_delta // 8} us")

        # Zero both buffers (really just DAC writes with a zero argument)
        _zero_sample_buf(ULP_BASE + ULP_SAMPLE_ARRAY0, _RTC_BUFFER_SLICE_WIDTH, 65535)  # type: ignore
        _zero_sample_buf(ULP_BASE + ULP_SAMPLE_ARRAY1, _RTC_BUFFER_SLICE_WIDTH, 65535)  # type: ignore
        self.last_buf_filled = 0

    def play(self):
        self.audio_f.setpos(0)

        # TODO: SET UP ISRS
        self.isr_pump = Timer(-1)
        self.isr_read_file = Timer(-1)

        self.isr_pump.init(mode=Timer.PERIODIC, freq=121, callback=_pump_samples_isr)
        self.isr_read_file.init(mode=Timer.PERIODIC, freq=5, callback=_buffer_fill_thread_isr)

        self.ulp.run(ULP_ENTRY)

@micropython.native
def _buffer_fill_thread_isr(_: Timer):
    self = SINGLETON_AUDIO_PLAYER

    self.sample_buffer_ptr = self.sample_buffer_size - 1

    # TODO: may need to double buffer this one too for performance/stuttering
    # reasons.
    if self.sample_buffer_ptr >= self.sample_buffer_size - _RTC_BUFFER_SLICE_WIDTH:
        t_start = time.ticks_ms()
        b_read = self.audio_f.readframes_into(self.sample_buffer)
        t_end = time.ticks_ms()
        print(f"buf refill {time.ticks_diff(t_end, t_start)} ms")

        # TODO: Handle b_read

        self.sample_buffer_ptr = 0

        gc.collect()

@micropython.native
# MUST OCCUR AT LEAST 121 times a second!
def _pump_samples_isr(_: Timer):
    self = SINGLETON_AUDIO_PLAYER

    # Determine back buffer
    idle_array = mem8[ULP_BASE + ULP_ACTIVE_ARRAY]

    if idle_array == self.last_buf_filled:
        #time.sleep_ms(500)
        #print(f"current idle array: {idle_array}")
        #ulp.run(ULP_ENTRY)
        return

    if self.sample_buffer_ptr >= self.sample_buffer_size:
        print("ERROR UNDERFLOW!!!!")
        _zero_sample_buf(ULP_BASE + ULP_SAMPLE_ARRAY0, _RTC_BUFFER_SLICE_WIDTH, self.sample_cycles_delta)  # type: ignore
        _zero_sample_buf(ULP_BASE + ULP_SAMPLE_ARRAY1, _RTC_BUFFER_SLICE_WIDTH, self.sample_cycles_delta)  # type: ignore
        _buffer_fill_thread_isr(_)  # Force buffer refill.
        return

    #print(f"current idle array: {idle_array}")
    array_offset = ULP_SAMPLE_ARRAY0 if idle_array == 0 else ULP_SAMPLE_ARRAY1

    # NOTE: Buffer rewrite is too slow??
    #t_start = time.ticks_ms()
    jit_sample_buf(ULP_BASE + array_offset, self.sample_buffer[buffer_ptr:], _RTC_BUFFER_SLICE_WIDTH, self.sample_cycles_delta - _ULP_CLKS_WRITE_DELAY)
    #t_end = time.ticks_ms()
    #print(f"ncg {time.ticks_diff(t_end, t_start)} ms")
    self.sample_buffer_ptr += _RTC_BUFFER_SLICE_WIDTH
    #print(f"buffer ptr {buffer_ptr}")

    #print(f"sample range {max_amp - min_amp} min amplitude {min_amp}")

    #out_asm = gen_memdmp_binary(ULP_BASE + ULP_ENTRY, 5888 - ULP_ENTRY)
    #print(out_asm)

    self.last_buf_filled = idle_array

    #time.sleep(5)


SINGLETON_AUDIO_PLAYER = AudioPlayer()